<script lang="ts">
 import {onMount,untrack} from 'svelte';import * as env from '$app/env/public';import {loadGoogleMaps} from './google-maps';
 let {record,date,layer,boundary}:{record:any,date:string,layer:string,boundary?:any}=$props();
 let element:HTMLDivElement,map:google.maps.Map|undefined,overlay:google.maps.GroundOverlay|undefined,outline:google.maps.Polygon|undefined;
 let ready=$state(false),busy=$state(false),message=$state('Preparing your field map…'),opacity=$state(.65),mode=$state('satellite'),shown=$state(false),details=$state<any>(null);
 let disposed=false,controller:AbortController|undefined,version=0;
 function fit(){if(!map||!boundary?.coordinates?.[0])return;const bounds=new google.maps.LatLngBounds();for(const p of boundary.coordinates[0])bounds.extend({lat:p[1],lng:p[0]});map.fitBounds(bounds,65);}
 onMount(()=>{disposed=false;void loadGoogleMaps(env.PUBLIC_GOOGLE_MAPS_API_KEY||'').then(api=>{if(disposed)return;map=new api.Map(element,{center:{lat:-17.8,lng:31.05},zoom:12,maxZoom:22,mapTypeId:'satellite',mapTypeControl:false,streetViewControl:false,fullscreenControl:true,tilt:0});ready=true;}).catch(e=>{if(!disposed)message=e.message;});return()=>{disposed=true;version++;controller?.abort();overlay?.setMap(null);outline?.setMap(null);};});
 $effect(()=>{if(!ready||!map||!boundary?.coordinates?.[0])return;const paths=boundary.coordinates[0].map((p:number[])=>({lat:p[1],lng:p[0]}));outline?.setMap(null);outline=new google.maps.Polygon({map,paths,strokeColor:'#ffffff',strokeWeight:2,fillOpacity:0,clickable:false});fit();});
 $effect(()=>{const id=record.id,d=date,l=layer;if(!ready||!id||!d||!l)return;untrack(()=>void load());});
 $effect(()=>{const loaded=ready;void loaded;overlay?.setOpacity(Number(opacity));map?.setMapTypeId(mode);});
 async function load(){const token=++version;controller?.abort();controller=new AbortController();const signal=controller.signal;overlay?.setMap(null);shown=false;details=null;busy=true;message='Requesting georeferenced satellite pixels…';const requested={monitoring:record.id,date,layer};
 try{for(let attempt=0;attempt<4;attempt++){const response=await fetch('/api/satellite/overlay',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(requested),signal});const result=await response.json();if(disposed||token!==version)return;if(result.state==='pending'){message='Farmonaut is preparing this raster. Your actual field boundary is shown below.';await new Promise(resolve=>setTimeout(resolve,2000));continue;}if(!response.ok||result.state!=='ready')throw Error(result.error||'Georeferenced imagery is not available.');if(result.value.sample)throw Error('Sample pixels cannot be aligned to your real field.');overlay=new google.maps.GroundOverlay(result.value.url,result.value.bounds,{opacity:Number(opacity),clickable:false});overlay.setMap(map!);details=result.value;shown=true;fit();message='Verified georeferenced '+layer.toUpperCase()+' pixels · '+date+'.';return;}message='The georeferenced raster is still processing. Retry shortly.';
 }catch(e){if(!disposed&&token===version&&!signal.aborted)message=e instanceof Error?e.message:'Mapped imagery unavailable.';}finally{if(!disposed&&token===version)busy=false;}}
</script>
<section class="geo-map" aria-label="Geographic crop monitoring"><div class="map-toolbar"><label>Basemap<select bind:value={mode}><option value="satellite">Satellite</option><option value="hybrid">Hybrid</option><option value="roadmap">Street</option><option value="terrain">Terrain</option></select></label><label>Data opacity <span>{Math.round(Number(opacity)*100)}%</span><input aria-label="Data opacity" type="range" min="0" max="1" step="0.05" bind:value={opacity}/></label><button type="button" class="p-button subtle" disabled={!ready} onclick={fit}>Fit field</button><button type="button" class="p-button subtle" disabled={!ready||busy||!date} onclick={load}>{busy?'Loading overlay…':'Retry overlay'}</button></div><div class="map-stage"><div class="map" bind:this={element}></div><div class="map-badge"><span>{layer.toUpperCase()} / {date||'Awaiting observation'}</span><strong>{shown?'Satellite overlay active':busy?'Preparing satellite overlay':'Field boundary · overlay unavailable'}</strong></div></div><div class="map-status" class:available={shown} role="status"><strong>{shown?'Mapped observation':busy?'Preparing mapped observation':'Satellite overlay needs attention'}</strong><p>{message}</p>{#if details}<p>Raster grid: {details.width} × {details.height} pixels. {details.source}. Opacity blends data with the Google basemap.</p>{/if}{#if !shown&&!busy}<p>The map shows your saved boundary. The original provider image remains available in the image tab; it is not stretched onto the map without verified geographic bounds.</p>{/if}</div><p class="caption">Satellite pixels describe the selected index and acquisition date. The Google basemap may be from a different date. Field-wide advice does not locate individual pests or nutrient deficiencies; coloured zones require spatial data. Small fields can contain only a few source pixels, so genuine uniform areas remain uniform.</p></section>
<style>.geo-map{background:#fffef8;color:#163f32}.map-toolbar{display:flex;gap:14px;flex-wrap:wrap;align-items:end;padding:18px 22px;border-bottom:1px solid #dce4d3}.map-toolbar label{display:grid;gap:6px;font-size:11px}.map-toolbar label span{font-size:10px;color:#60735e}.map-toolbar select{padding:9px;font-size:12px}.map-toolbar .p-button{font-size:11px;padding:11px 14px}.map-stage{position:relative}.map{height:580px;background:#eaf0e2}.map-badge{position:absolute;top:14px;left:14px;max-width:calc(100% - 80px);background:#143f33ef;color:#fff;padding:12px 16px;border-radius:9px;pointer-events:none;box-shadow:0 3px 18px #0002}.map-badge span{display:block;font-size:9px;letter-spacing:.1em;color:#d7e99b}.map-badge strong{display:block;font-size:11px;font-weight:500;margin-top:6px}.map-status{padding:16px 22px;background:#f6efdc;border-top:1px solid #e4dcc1}.map-status.available{background:#eef4e3}.map-status strong{font-size:12px}.map-status p{font-size:11px;margin:6px 0 0;line-height:1.7}.caption{padding:16px 22px;margin:0;font-size:10px!important;line-height:1.8;color:#61745e}@media(max-width:600px){.map{height:430px}.map-toolbar{padding:14px;gap:10px}.map-status{padding:14px}.caption{padding:14px}.map-badge{left:10px;top:10px;padding:10px}.map-toolbar input{max-width:140px}}</style>
